#' Get commentary for a specific figure from the combined list
#' @param commentary_list Named list from generate_all_commentary()
#' @param figure_id Figure identifier
#' @return Commentary list or NULL
get_figure_commentary <- function(commentary_list, figure_id) {
    if (is.null(commentary_list)) return(NULL)
    commentary_list[[figure_id]]
}


#' Format commentary as HTML for embedding in Rmd reports
#' @param commentary Commentary list for a single figure
#' @return HTML string
format_commentary_html <- function(commentary) {
    if (is.null(commentary)) return("")

    html <- "<div class='commentary-block' style='background: #f8f9fa; border-left: 4px solid #4a90d9; padding: 12px 16px; margin: 10px 0 20px 0; border-radius: 0 4px 4px 0; font-size: 0.92em;'>\n"

    # What is this figure
    html <- paste0(html, "<p style='margin: 0 0 8px 0;'><strong>What this shows:</strong> ",
                   htmltools::htmlEscape(commentary$what_is_this %||% ""), "</p>\n")

    # Biological interpretation (new field — the main prose paragraph)
    bio_interp <- commentary$biological_interpretation %||% ""
    if (nzchar(bio_interp)) {
        html <- paste0(html, "<p style='margin: 4px 0 8px 0;'><strong>Interpretation:</strong> ",
                       htmltools::htmlEscape(bio_interp), "</p>\n")
    }

    # Observations
    obs <- commentary$observations
    if (length(obs) > 0 && obs[[1]] != "") {
        html <- paste0(html, "<p style='margin: 4px 0;'><strong>Key observations:</strong></p>\n<ul style='margin: 2px 0 8px 0; padding-left: 20px;'>\n")
        for (o in obs) {
            html <- paste0(html, "<li>", htmltools::htmlEscape(o), "</li>\n")
        }
        html <- paste0(html, "</ul>\n")
    }

    # Statistical assessment (new field)
    stat_assess <- commentary$statistical_assessment %||% ""
    if (nzchar(stat_assess)) {
        html <- paste0(html, "<p style='margin: 4px 0 8px 0;'><strong>Statistical note:</strong> ",
                       htmltools::htmlEscape(stat_assess), "</p>\n")
    }

    # Issues / checks
    issues <- commentary$issues_checks
    if (length(issues) > 0 && issues[[1]] != "") {
        html <- paste0(html, "<p style='margin: 4px 0;'><strong>Checks:</strong></p>\n<ul style='margin: 2px 0 8px 0; padding-left: 20px;'>\n")
        for (issue in issues) {
            html <- paste0(html, "<li>", htmltools::htmlEscape(issue), "</li>\n")
        }
        html <- paste0(html, "</ul>\n")
    }

    # Next steps
    steps <- commentary$next_steps
    if (length(steps) > 0 && steps[[1]] != "") {
        html <- paste0(html, "<p style='margin: 4px 0;'><strong>Next steps:</strong></p>\n<ul style='margin: 2px 0 4px 0; padding-left: 20px;'>\n")
        for (s in steps) {
            html <- paste0(html, "<li>", htmltools::htmlEscape(s), "</li>\n")
        }
        html <- paste0(html, "</ul>\n")
    }

    # Footer with attribution
    backend <- commentary$backend %||% "unknown"
    confidence <- commentary$confidence %||% ""
    backend_label <- if (grepl("claude", backend, ignore.case = TRUE)) {
        "Claude (Anthropic) + K-Dense AI scientific-skills"
    } else if (grepl("openai", backend, ignore.case = TRUE)) {
        "OpenAI + K-Dense AI scientific-skills"
    } else if (backend == "data_driven") {
        "data-driven + K-Dense AI scientific-skills"
    } else {
        backend
    }
    if (nzchar(confidence) && confidence != "none") {
        backend_label <- paste0(backend_label, " | confidence: ", confidence)
    }
    html <- paste0(html, "<p style='margin: 4px 0 0 0; color: #888; font-size: 0.85em;'>",
                   "<em>Generated by: ", htmltools::htmlEscape(backend_label), "</em></p>\n")

    html <- paste0(html, "</div>\n")
    html
}
